mapper.select:
SELECT cs.student_id, cs.class_id, c.class_name, g.grade_name FROM class_student cs JOIN class c ON c.id = cs.class_id AND c.deleted = 0 LEFT JOIN grade g ON g.id = c.grade_id AND g.deleted = 0 WHERE cs.student_id IN
#{id}
ORDER BY cs.student_id, cs.class_id

SELECT student_id
FROM class_student
WHERE class_id = #{classId}

mapper.delete:
DELETE FROM class_student
WHERE student_id = #{studentId}
  AND class_id = #{classId}
